def page(path, title, desc, body, ldx="", crumbs=None, prio="0.7", img="og.jpg"):
    t = head(title, desc, path, ld({"@context": "https://schema.org", "@graph": [NEG]}) + ldx + (bc_ld(crumbs) if crumbs else ""), img) + header() + (bc(crumbs) if crumbs else "") + body + footer()
