JS = """(function(){var K='bm_cart',WA='%s',P=%s;function g(){try{return JSON.parse(localStorage.getItem(K)||'{}')}catch(e){return{}}}function s(c){try{localStorage.setItem(K,JSON.stringify(c))}catch(e){}r()}
function cop(n){return '$'+String(n).replace(/\\B(?=(\\d{3})+(?!\\d))/g,'.')}
function t(m){var x=document.getElementById('toast');if(!x)return;x.textContent=m;x.style.display='block';setTimeout(function(){x.style.display='none'},1800)}
function r(){var c=g(),n=0,tot=0;for(var k in P){var q=+c[k]||0;n+=q;tot+=q*P[k][0];var i=document.getElementById('q-'+k);if(i&&document.activeElement!==i)i.value=q}var cn=document.getElementById('cn');if(cn)cn.textContent=n;var tt=document.getElementById('tt');if(tt)tt.textContent=cop(tot)}
document.addEventListener('click',function(e){var a=e.target.closest('[data-add]');if(a){var c=g(),k=a.getAttribute('data-add');c[k]=(+c[k]||0)+1;s(c);t('Agregado a tu pedido');if(!a.closest('.pc')){location.href=document.querySelector('.cartb').getAttribute('href')}return}
var m=e.target.closest('[data-m]'),p=e.target.closest('[data-p]');if(m||p){var c2=g(),k2=(m||p).getAttribute(m?'data-m':'data-p');c2[k2]=Math.max(0,(+c2[k2]||0)+(m?-1:1));s(c2)}});
document.addEventListener('input',function(e){if(e.target.id&&e.target.id.indexOf('q-')===0){var c=g();c[e.target.id.slice(2)]=Math.max(0,parseInt(e.target.value)||0);try{localStorage.setItem(K,JSON.stringify(c))}catch(x){}r()}});
var f=document.getElementById('pf');if(f)f.addEventListener('submit',function(e){e.preventDefault();var c=g(),l=[],tot=0;for(var k in P){var q=+c[k]||0;if(q){l.push('• '+P[k][1]+' x'+q+' = '+cop(q*P[k][0]));tot+=q*P[k][0]}}if(!l.length){t('Elige al menos un protector');return}
var m='Hola, quiero hacer este pedido contra entrega:\\n'+l.join('\\n')+'\\nTotal: '+cop(tot)+'\\nNombre: '+document.getElementById('nm').value+'\\nCelular: '+document.getElementById('tl').value+'\\nCiudad: '+document.getElementById('ci').value+'\\nDirección: '+document.getElementById('dr').value+(document.getElementById('nt').value?'\\nNotas: '+document.getElementById('nt').value:'');window.open('https://wa.me/'+WA+'?text='+encodeURIComponent(m),'_blank')});
r()})();""" % (WA, json.dumps(PR))
